const crypto = require('crypto');
const item = $input.first().json;
const headers = item.headers || {};
const lower = Object.fromEntries(Object.entries(headers).map(([k, v]) => [String(k).toLowerCase(), v]));
const wid = String(lower['webhook-id'] || '');
const ts = String(lower['webhook-timestamp'] || '');
const sig = String(lower['webhook-signature'] || '');
const secret = String($env.WHOP_WEBHOOK_SECRET || '');
if (!secret || !wid || !ts || !sig) {
  return [{ json: { ok: false, httpStatus: 401, error: 'missing_signature_or_secret' } }];
}
const skew = Math.abs(Math.floor(Date.now() / 1000) - Number(ts));
if (!Number.isFinite(skew) || skew > 300) {
  return [{ json: { ok: false, httpStatus: 401, error: 'stale_timestamp' } }];
}
const rawBody = typeof item.rawBody === 'string' ? item.rawBody : JSON.stringify(item.body || item);
const keyBytes = secret.startsWith('ws_') ? Buffer.from(secret.slice(3), 'base64') : Buffer.from(secret, 'utf8');
const expectedSig = crypto.createHmac('sha256', keyBytes).update(`${wid}.${ts}.${rawBody}`).digest('base64');
const validSig = sig.split(/\s+/).some((part) => {
  const [, val] = part.split(',');
  return val && val.length === expectedSig.length && crypto.timingSafeEqual(Buffer.from(val), Buffer.from(expectedSig));
});
if (!validSig) {
  return [{ json: { ok: false, httpStatus: 401, error: 'bad_signature' } }];
}

const payload = item.body || item;
const ev = String(payload.action || payload.event || '').toLowerCase();
const data = payload.data || payload;
const meta = data.metadata || {};
const planId = String(data.variant_id || data.plan_id || (data.plan && data.plan.id) || meta.plan_id || '');
const email = String(data.customer_email || data.email || meta.email || '').trim().toLowerCase();
const discordUserId = String(meta.discord_user_id || data.discord_user_id || '');
const amount = Number((data.total && data.total.amount) || data.amount || 0);
const isFreeOtp = planId === 'plan_TEMPLATE_01' && amount <= 0;

return [{
  json: {
    ok: true,
    httpStatus: 200,
    event: ev,
    planId,
    email,
    discordUserId,
    amount,
    isFreeOtp,
    isPaid: !isFreeOtp && ev === 'payment.succeeded',
    isRevoke: ev === 'refund.created' || ev === 'membership.deactivated',
    invitePayload: { max_age: 900, max_uses: 1, temporary: false, unique: true }
  }
}];
